SELECT 
FROM medical_record


        AND patient_id = #{patientId}


        AND (patient_name LIKE CONCAT('%', #{keyword}, '%')
             OR diagnosis LIKE CONCAT('%', #{keyword}, '%')
             OR hospital LIKE CONCAT('%', #{keyword}, '%'))


        AND type = #{type}


        AND date >= #{startDate}


        AND date <= #{endDate}


ORDER BY date DESC, create_time DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT COUNT(*) FROM medical_record


        AND patient_id = #{patientId}


        AND (patient_name LIKE CONCAT('%', #{keyword}, '%')
             OR diagnosis LIKE CONCAT('%', #{keyword}, '%')
             OR hospital LIKE CONCAT('%', #{keyword}, '%'))


        AND type = #{type}


        AND date >= #{startDate}


        AND date <= #{endDate}

SELECT mr.id, mr.patient_id, mr.patient_name, mr.type, mr.diagnosis, mr.hospital,
       mr.department, mr.doctor_name, mr.date, mr.content, mr.attachments, mr.create_time
FROM medical_record mr
INNER JOIN patient p ON mr.patient_id = p.id
WHERE p.doctor_id = #{doctorId}

    AND (mr.patient_name LIKE CONCAT('%', #{request.keyword}, '%')
         OR mr.diagnosis LIKE CONCAT('%', #{request.keyword}, '%')
         OR mr.hospital LIKE CONCAT('%', #{request.keyword}, '%'))


    AND mr.type = #{request.type}


    AND mr.date >= #{request.startDate}


    AND mr.date <= #{request.endDate}

ORDER BY mr.date DESC, mr.create_time DESC
LIMIT #{request.pageSize} OFFSET #{request.offset}

SELECT COUNT(*)
FROM medical_record mr
INNER JOIN patient p ON mr.patient_id = p.id
WHERE p.doctor_id = #{doctorId}

    AND (mr.patient_name LIKE CONCAT('%', #{request.keyword}, '%')
         OR mr.diagnosis LIKE CONCAT('%', #{request.keyword}, '%')
         OR mr.hospital LIKE CONCAT('%', #{request.keyword}, '%'))


    AND mr.type = #{request.type}


    AND mr.date >= #{request.startDate}


    AND mr.date <= #{request.endDate}
